阅读程序，写出运行结果：
#include <stdio.h>
int main(void)
{
    int n = 5, s = 0;
    while (n < 3)
    {
        s += n;
        n++;
    }
    printf("A=%d,", s);
    n = 5; s = 0;
    do
    {
        s += n;
        n++;
    } while (n < 3);
    printf("B=%d\n", s);
    return 0;
}

阅读程序，用表格法逐行跟踪后写出全部运行结果：
#include <stdio.h>
int main(void)
{
    int i, j, s = 0;
    for (i = 1; i <= 3; i++)
    {
        for (j = 1; j <= i; j++)
        {
            if (j % 2 == 0)
                continue;
            s += i * j;
        }
        printf("%d,%d\n", i, s);
    }
    printf("s=%d\n", s);
    return 0;
}
要求：列出每一步的 i、j、j%2、s 及走向（continue 记 C，内层结束记止）。

